y_gallery_cards_2_metaLeft":{"limit":2500,"kind":"text"},"activity_gallery_cards_2_metaRight":{"limit":2500,"kind":"text"},"activity_gallery_cards_2_linkTo":{"limit":1000,"kind":"route"},"activity_gallery_cards_3_image":{"limit":1000,"kind":"image"},"activity_gallery_cards_3_badge":{"limit":2500,"kind":"text"},"activity_gallery_cards_3_title":{"limit":2500,"kind":"text"},"activity_gallery_cards_3_description":{"limit":2500,"kind":"text"},"activity_gallery_cards_3_metaLeft":{"limit":2500,"kind":"text"},"activity_gallery_cards_3_metaRight":{"limit":2500,"kind":"text"},"activity_gallery_cards_4_image":{"limit":1000,"kind":"image"},"activity_gallery_cards_4_badge":{"limit":2500,"kind":"text"},"activity_gallery_cards_4_title":{"limit":2500,"kind":"text"},"activity_gallery_cards_4_description":{"limit":2500,"kind":"text"},"activity_gallery_cards_4_metaLeft":{"limit":2500,"kind":"text"},"activity_gallery_cards_4_metaRight":{"limit":2500,"kind":"text"},"activity_gallery_cards_5_image":{"limit":1000,"kind":"image"},"activity_gallery_cards_5_badge":{"limit":2500,"kind":"text"},"activity_gallery_cards_5_title":{"limit":2500,"kind":"text"},"activity_gallery_cards_5_description":{"limit":2500,"kind":"text"},"activity_gallery_cards_5_metaLeft":{"limit":2500,"kind":"text"},"activity_gallery_cards_5_metaRight":{"limit":2500,"kind":"text"},"activity_etiquette_eyebrow":{"limit":2500,"kind":"text"},"activity_etiquette_title":{"limit":2500,"kind":"text"},"activity_etiquette_items_0_title":{"limit":2500,"kind":"text"},"activity_etiquette_items_0_description":{"limit":2500,"kind":"text"},"activity_etiquette_items_1_title":{"limit":2500,"kind":"text"},"activity_etiquette_items_1_description":{"limit":2500,"kind":"text"},"activity_etiquette_items_2_title":{"limit":2500,"kind":"text"},"activity_etiquette_items_2_description":{"limit":2500,"kind":"text"},"activity_card_visible_0":{"limit":5,"kind":"visible"},"activity_card_order_0":{"limit":12,"kind":"number"},"activity_card_visible_1":{"limit":5,"kind":"visible"},"activity_card_order_1":{"limit":12,"kind":"number"},"activity_card_visible_2":{"limit":5,"kind":"visible"},"activity_card_order_2":{"limit":12,"kind":"number"},"activity_card_visible_3":{"limit":5,"kind":"visible"},"activity_card_order_3":{"limit":12,"kind":"number"},"activity_card_visible_4":{"limit":5,"kind":"visible"},"activity_card_order_4":{"limit":12,"kind":"number"},"activity_card_visible_5":{"limit":5,"kind":"visible"},"activity_card_order_5":{"limit":12,"kind":"number"}},"contact":{"title":{"limit":200,"kind":"text"},"description":{"limit":2500,"kind":"text"},"link_url":{"limit":1000,"kind":"url"},"link_label":{"limit":150,"kind":"text"}}}$spec$::jsonb;
BEGIN
 IF jsonb_typeof(NEW.content)<>'object' OR octet_length(NEW.content::text)>64000 THEN RAISE EXCEPTION 'Page content exceeds allowed size'; END IF;
 FOR item IN SELECT key,value FROM jsonb_each(NEW.content) LOOP
  field:=specs->NEW.section->item.key;
  IF field IS NULL OR jsonb_typeof(item.value)<>'string' THEN RAISE EXCEPTION 'Invalid page field'; END IF;
  text_value:=item.value#>>'{}';kind:=field->>'kind';
  IF length(text_value)>(field->>'limit')::integer THEN RAISE EXCEPTION 'Page field is too long'; END IF;
  IF btrim(text_value)='' THEN CONTINUE; END IF;
  IF kind='number' AND text_value!~'^([0-9]{1,9})(\.[0-9]{1,2})?$' THEN RAISE EXCEPTION 'Use a non-negative number'; END IF;
  IF kind='visible' AND text_value NOT IN ('true','false') THEN RAISE EXCEPTION 'Invalid visibility'; END IF;
  IF kind='image' AND text_value!~'^(https://[^/@[:space:]]+([/?#].*)?|/images/[a-zA-Z0-9/_ .%\-]+|/site-images/[0-9a-f-]{36}/[0-9a-f-]{36}\.(jpg|png|webp))$' THEN RAISE EXCEPTION 'Invalid image reference'; END IF;
  IF kind='url' AND text_value!~'^https://[^/@[:space:]]+([/?#].*)?$' THEN RAISE EXCEPTION 'Use an HTTPS URL without credentials'; END IF;
  IF kind='route' AND text_value!~'^(https://[^/@[:space:]]+([/?#].*)?|/[a-zA-Z0-9][a-zA-Z0-9/?#=&._%\-]*)$' THEN RAISE EXCEPTION 'Invalid link'; END IF;
  IF kind='map' AND text_value!~'^https://(maps\.google\.com|www\.google\.com)/[^[:space:]@]*$' THEN RAISE EXCEPTION 'Invalid map URL'; END IF;
 END LOOP;
 NEW.updated_at:=clock_timestamp();NEW.updated_by:=auth.uid();
 IF TG_OP='UPDATE' THEN NEW.revision:=OLD.revision+1;END IF;
 RETURN NEW;
END $function$;
REVOKE ALL ON FUNCTION private.validate_site_page_content() FROM PUBLIC,anon,authenticated;

-- Uploaded draft images stay private until a published page references them.
INSERT INTO storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
 VALUES('site-images','site-images',false,3145728,ARRAY['image/jpeg','image/png','image/webp'])
 ON CONFLICT(id) DO NOTHING;
CREATE POLICY "Content team uploads website images" ON storage.objects FOR INSERT TO authenticated
 WITH CHECK(bucket_id='site-images' AND private.get_user_role() IN ('owner','team_member') AND (storage.foldername(name))[1]=auth.uid()::text AND name~'^[0-9a-f-]{36}/[0-9a-f-]{36}\.(jpg|png|webp)$');
CREATE POLICY "Content team previews website images" ON storage.objects FOR SELECT TO authenticated
 USING(bucket_id='site-images' AND private.get_user_role() IN ('owner','team_member'));
CREATE POLICY "Published website images are readable" ON storage.objects FOR SELECT TO anon,authenticated
 USING(bucket_id='site-images' AND EXISTS(
  SELECT 1 FROM public.site_page_content p, LATERAL jsonb_each_text(p.content) value
  WHERE p.stage='published' AND value.value='/site-images/'||storage.objects.name
 ));
-- No update/delete policy: every upload has a new immutable path; replacing a draft never deletes a live image.
COMMIT;
